package io.github.describeadmin.codegen.generator;

import io.github.describeadmin.codegen.model.FieldSpec;
import io.github.describeadmin.codegen.model.ModuleSpec;
import io.github.describeadmin.codegen.parser.SpecLoader;
import org.junit.jupiter.api.Test;

import java.nio.file.Path;
import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;

class DdlGeneratorMutaGate1Test {

    @Test
    void generatesExactColumnLinesEscapingOrderingAndKeys() throws Exception {
        ModuleSpec loaded = SpecLoader.load(Path.of("examples/project.yaml"));
        FieldSpec base = loaded.fields().get(0);

        FieldSpec a = new FieldSpec("alpha", "col_a", base.type(), base.length(), base.precision(),
                base.scale(), false, "it's a", base.query(), true);
        FieldSpec b = new FieldSpec("beta", "col_b", base.type(), base.length(), base.precision(),
                base.scale(), true, "plain", base.query(), false);

        ModuleSpec spec = new ModuleSpec(loaded.basePackage(), loaded.module(), loaded.entity(),
                "t_demo", "it's table", loaded.apiPrefix(), loaded.layout(), loaded.layoutOrigin(),
                List.of(a, b));

        String ddl = DdlGenerator.generate(spec);

        String type = String.format("%-11s", a.sqlColumnType());
        String lineA = String.format("%-14s", "col_a") + " " + type + " NOT NULL COMMENT 'it''s a'";
        String lineB = String.format("%-14s", "col_b") + " "
                + String.format("%-11s", b.sqlColumnType()) + "     NULL COMMENT 'plain'";

        // header comment is unescaped, table comment clause is escaped
        assertThat(ddl).startsWith("-- it's table\n--\n");
        assertThat(ddl).contains("CREATE TABLE IF NOT EXISTS t_demo (\n  ");
        assertThat(ddl).contains("COMMENT='it''s table';");

        assertThat(ddl).contains(lineA).contains(lineB);

        // fixed ordering: id, business fields, audit fields, primary key, secondary keys
        int idPos = ddl.indexOf("COMMENT '主键'");
        int aPos = ddl.indexOf(lineA);
        int bPos = ddl.indexOf(lineB);
        int auditPos = ddl.indexOf("COMMENT '创建人'");
        int pkPos = ddl.indexOf("PRIMARY KEY (id)");
        assertThat(idPos).isPositive();
        assertThat(aPos).isGreaterThan(idPos);
        assertThat(bPos).isGreaterThan(aPos);
        assertThat(auditPos).isGreaterThan(bPos);
        assertThat(pkPos).isGreaterThan(auditPos);

        // only the indexed field gets a key; keys are last, joined by ",\n  "
        assertThat(ddl).contains("COMMENT '乐观锁版本号',\n  PRIMARY KEY (id),\n"
                + "  KEY idx_t_demo_col_a (col_a)\n) ENGINE=InnoDB\n"
                + "  DEFAULT CHARACTER SET utf8mb4\n  COLLATE utf8mb4_general_ci\n");
        assertThat(ddl).doesNotContain("idx_t_demo_col_b");
        assertThat(ddl).contains(lineA + ",\n  " + lineB + ",\n  ");
    }
}

package io.github.describeadmin.codegen.generator;

import io.github.describeadmin.codegen.model.FieldSpec;
import io.github.describeadmin.codegen.model.ModuleSpec;
import io.github.describeadmin.codegen.parser.SpecLoader;
import org.junit.jupiter.api.Test;

import java.nio.file.Path;
import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;

class DdlGeneratorMutaGate2Test {

    @Test
    void escapesQuotesAndRendersNullabilityIndexAndOrdering() throws Exception {
        ModuleSpec base = SpecLoader.load(Path.of("examples/project.yaml"));
        FieldSpec f = base.fields().get(0);

        FieldSpec notNullIndexed = new FieldSpec(f.name(), "first_col", f.type(), f.length(),
                f.precision(), f.scale(), false, "it's", f.query(), true);
        FieldSpec nullablePlain = new FieldSpec(f.name(), "other_col", f.type(), f.length(),
                f.precision(), f.scale(), true, "plain", f.query(), false);

        ModuleSpec s = new ModuleSpec(base.basePackage(), base.module(), base.entity(),
                base.table(), "O'Brien's", base.apiPrefix(), base.layout(),
                base.layoutOrigin(), List.of(notNullIndexed, nullablePlain));

        String ddl = DdlGenerator.generate(s);

        // header comment is raw, table comment is escaped
        assertThat(ddl).startsWith("-- O'Brien's\n--\n");
        assertThat(ddl).contains("COMMENT='O''Brien''s';");

        // column comment escaped, nullability rendered
        assertThat(ddl).contains("NOT NULL COMMENT 'it''s'");
        assertThat(ddl).contains("    NULL COMMENT 'plain'");

        // only the indexed field gets a secondary key
        String idx = "KEY idx_" + s.table() + "_first_col (first_col)";
        assertThat(ddl).contains(idx);
        assertThat(ddl).doesNotContain("idx_" + s.table() + "_other_col");
        assertThat(ddl.split("KEY idx_", -1)).hasSize(2);

        // secondary keys come last, directly before the table options
        assertThat(ddl).contains(idx + "\n) ENGINE=InnoDB\n  DEFAULT CHARACTER SET utf8mb4");

        // ordering: id, business columns, audit columns, primary key, secondary key
        int id = ddl.indexOf("id ");
        int first = ddl.indexOf("first_col ");
        int other = ddl.indexOf("other_col ");
        int createBy = ddl.indexOf("create_by");
        int createTime = ddl.indexOf("create_time");
        int updateBy = ddl.indexOf("update_by");
        int updateTime = ddl.indexOf("update_time");
        int deleted = ddl.indexOf("deleted ");
        int version = ddl.indexOf("version ");
        int pk = ddl.indexOf("PRIMARY KEY (id)");
        int key = ddl.indexOf(idx);
        assertThat(List.of(id, first, other, createBy, createTime, updateBy, updateTime,
                deleted, version, pk, key)).isSorted();
        assertThat(id).isGreaterThanOrEqualTo(0);

        // comma separators between items
        assertThat(ddl).contains(",\n  PRIMARY KEY (id),\n  " + idx);
    }
}

package io.github.describeadmin.codegen.generator;

import io.github.describeadmin.codegen.model.FieldSpec;
import io.github.describeadmin.codegen.model.FieldType;
import io.github.describeadmin.codegen.model.Layout;
import io.github.describeadmin.codegen.model.ModuleSpec;
import org.junit.jupiter.api.Test;

import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

class DdlGeneratorMutaGate3Test {

    private static FieldSpec field(String name, String column, boolean nullable,
                                   String comment, boolean indexed) {
        return new FieldSpec(name, column, FieldType.values()[0], 10, 10, 2,
                nullable, comment, FieldSpec.QueryMode.NONE, indexed);
    }

    private static String lineStarting(String ddl, String prefix) {
        for (String line : ddl.split("\n")) {
            if (line.strip().startsWith(prefix)) {
                return line;
            }
        }
        throw new AssertionError("no line starting with " + prefix + " in:\n" + ddl);
    }

    @Test
    void generatesOrderedColumnsEscapedCommentsAndKeys() {
        ModuleSpec spec = new ModuleSpec("com.example", "demo", "Demo", "t_demo",
                "Bob's table", "/api/demo", Layout.values()[0], "test",
                List.of(
                        field("a", "col_a", false, "it's a", true),
                        field("b", "col_b", true, null, false),
                        field("c", "col_c", false, "plain", true)));

        String ddl = DdlGenerator.generate(spec);

        // header comment is raw, table COMMENT is escaped
        assertTrue(ddl.startsWith("-- Bob's table\n"));
        assertTrue(ddl.contains("CREATE TABLE IF NOT EXISTS t_demo ("));
        assertTrue(ddl.contains("COMMENT='Bob''s table';"));

        // column comment escaping and null comment handling
        String a = lineStarting(ddl, "col_a");
        assertTrue(a.contains("NOT NULL"));
        assertTrue(a.endsWith("COMMENT 'it''s a',"));
        String b = lineStarting(ddl, "col_b");
        assertFalse(b.contains("NOT NULL"));
        assertTrue(b.contains("    NULL"));
        assertTrue(b.endsWith("COMMENT '',"));

        // ordering: id, business columns, audit columns, primary key, indexes
        int id = ddl.indexOf("id            ");
        int ca = ddl.indexOf("col_a");
        int cb = ddl.indexOf("col_b");
        int cc = ddl.indexOf("col_c");
        int createBy = ddl.indexOf("create_by");
        int createTime = ddl.indexOf("create_time");
        int updateBy = ddl.indexOf("update_by");
        int updateTime = ddl.indexOf("update_time");
        int deleted = ddl.indexOf("deleted");
        int version = ddl.indexOf("version");
        int pk = ddl.indexOf("PRIMARY KEY (id)");
        int ka = ddl.indexOf("KEY idx_t_demo_col_a (col_a)");
        int kc = ddl.indexOf("KEY idx_t_demo_col_c (col_c)");
        assertTrue(id >= 0 && id < ca);
        assertTrue(ca < cb && cb < cc && cc < createBy);
        assertTrue(createBy < createTime && createTime < updateBy
                && updateBy < updateTime && updateTime < deleted && deleted < version);
        assertTrue(version < pk && pk < ka && ka < kc);
        assertFalse(ddl.contains("idx_t_demo_col_b"));

        // comma separation: last column and primary key end with commas, last key does not
        assertTrue(lineStarting(ddl, "version").endsWith(","));
        assertTrue(lineStarting(ddl, "PRIMARY KEY").endsWith(","));
        assertTrue(lineStarting(ddl, "KEY idx_t_demo_col_a").endsWith(","));
        assertEquals("  KEY idx_t_demo_col_c (col_c)", lineStarting(ddl, "KEY idx_t_demo_col_c"));
        assertTrue(ddl.contains("KEY idx_t_demo_col_c (col_c)\n) ENGINE=InnoDB"));
    }
}

package io.github.describeadmin.codegen.generator;

import io.github.describeadmin.codegen.model.FieldSpec;
import io.github.describeadmin.codegen.model.ModuleSpec;
import io.github.describeadmin.codegen.parser.SpecLoader;
import org.junit.jupiter.api.Test;

import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

class DdlGeneratorMutaGate4Test {

    @Test
    void escapesQuotesAndKeepsColumnLayoutAndOrder() throws Exception {
        ModuleSpec base = SpecLoader.load(Path.of("examples/project.yaml"));

        List<FieldSpec> fields = new ArrayList<>(base.fields());
        FieldSpec orig = fields.get(0);
        FieldSpec quoted = new FieldSpec(orig.name(), orig.column(), orig.type(), orig.length(),
                orig.precision(), orig.scale(), orig.nullable(), "it's", orig.query(),
                orig.indexed());
        fields.set(0, quoted);

        ModuleSpec s = new ModuleSpec(base.basePackage(), base.module(), base.entity(),
                base.table(), "O'Brien", base.apiPrefix(), base.layout(), base.layoutOrigin(),
                fields);

        String ddl = DdlGenerator.generate(s);

        // header comment is raw, table comment is escaped
        assertTrue(ddl.startsWith("-- O'Brien\n--\n"));
        assertTrue(ddl.contains("COMMENT='O''Brien';"));
        assertTrue(ddl.endsWith(";\n"));
        assertTrue(ddl.contains("CREATE TABLE IF NOT EXISTS " + base.table() + " (\n  id "));

        // exact id line and field line formatting
        String idLine = String.format("%-14s", "id") + " BIGINT      NOT NULL AUTO_INCREMENT COMMENT '主键'";
        String fieldLine = String.format("%-14s", quoted.column()) + " "
                + String.format("%-11s", quoted.sqlColumnType()) + " "
                + (quoted.nullable() ? "    NULL" : "NOT NULL")
                + " COMMENT 'it''s'";
        assertTrue(ddl.contains(idLine + ",\n  " + fieldLine + ",\n  "));

        // order: id, fields, audit columns, primary key, then indexes
        int idPos = ddl.indexOf(idLine);
        int fieldPos = ddl.indexOf(fieldLine);
        int createBy = ddl.indexOf(String.format("%-14s", "create_by"));
        int version = ddl.indexOf(String.format("%-14s", "version"));
        int pk = ddl.indexOf("PRIMARY KEY (id)");
        assertTrue(idPos < fieldPos);
        assertTrue(fieldPos < createBy);
        assertTrue(createBy < version);
        assertTrue(version < pk);

        // primary key line is followed by index lines only; no trailing comma before ")"
        assertTrue(ddl.contains("\n) ENGINE=InnoDB\n"));
        assertEquals(-1, ddl.indexOf(",\n)"));
    }
}

